     1→/**
     2→ * Public API endpoint for the storefront zip code widget.
     3→ *
     4→ * Called from the merchant's storefront (Theme App Extension or custom JS)
     5→ * to check whether a zip code is serviceable.
     6→ *
     7→ * GET/POST /api/zip-check?shop=store.myshopify.com&zip=12345
     8→ *
     9→ * Response:
    10→ *   200 { allowed: true,  message: "...", eta: "...", zone: "..." }
    11→ *   200 { allowed: false, message: "..." }
    12→ *   400 { error: "Missing shop or zip parameter" }
    13→ *   404 { allowed: false, message: "Zip code not found", notFound: true }
    14→ */
    15→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
    16→import db from "../db.server";
    17→import { normalizeZipCode } from "../utils/zip";
    18→
    19→function calculateDeliveryDate(
    20→  estimatedDays: string,
    21→  daysOfWeek: string | null,
    22→): string | null {
    23→  const match = estimatedDays.match(/^(\d+)/);
    24→  if (!match) return null;
    25→  const minDays = parseInt(match[1], 10);
    26→  if (isNaN(minDays) || minDays < 0) return null;
    27→
    28→  const deliveryDayNames = daysOfWeek
    29→    ? daysOfWeek.split(",").map((d) => d.trim().toLowerCase())
    30→    : ["mon", "tue", "wed", "thu", "fri"];
    31→
    32→  const dayMap: Record<string, number> = {
    33→    sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6,
    34→  };
    35→  const deliveryDayNumbers = new Set(
    36→    deliveryDayNames.map((d) => dayMap[d]).filter((n) => n !== undefined),
    37→  );
    38→
    39→  if (deliveryDayNumbers.size === 0) {
    40→    [1, 2, 3, 4, 5].forEach((d) => deliveryDayNumbers.add(d));
    41→  }
    42→
    43→  const date = new Date();
    44→  let businessDaysAdded = 0;
    45→
    46→  while (businessDaysAdded < minDays) {
    47→    date.setDate(date.getDate() + 1);
    48→    if (deliveryDayNumbers.has(date.getDay())) {
    49→      businessDaysAdded++;
    50→    }
    51→  }
    52→
    53→  while (!deliveryDayNumbers.has(date.getDay())) {
    54→    date.setDate(date.getDate() + 1);
    55→  }
    56→
    57→  return date.toISOString().split("T")[0];
    58→}
    59→
    60→const CORS_HEADERS = {
    61→  "Access-Control-Allow-Origin": "*",
    62→  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    63→  "Access-Control-Allow-Headers": "Content-Type",
    64→  "Content-Type": "application/json",
    65→};
    66→
    67→// Applied only to successful (allowed) ZIP check responses to reduce DB load
    68→// for repeated lookups of the same ZIP code from the same storefront visitor.
    69→const SUCCESS_HEADERS = {
    70→  ...CORS_HEADERS,
    71→  "Cache-Control": "public, max-age=60, stale-while-revalidate=120",
    72→};
    73→
    74→// Short cache for denied/not-found responses so merchants see changes quickly
    75→// (e.g. when they add a new ZIP code it takes effect within 5 seconds).
    76→const DENY_HEADERS = {
    77→  ...CORS_HEADERS,
    78→  "Cache-Control": "no-cache, max-age=5",
    79→};
    80→
    81→const SHOP_DOMAIN_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;
    82→
    83→async function handleZipCheck(shop: string | null, zip: string | null) {
    84→  if (!shop || !zip) {
    85→    return new Response(
    86→      JSON.stringify({ error: "Missing shop or zip parameter" }),
    87→      { status: 400, headers: CORS_HEADERS },
    88→    );
    89→  }
    90→
    91→  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
    92→  if (!SHOP_DOMAIN_RE.test(shop) || shop.length > 100) {
    93→    return new Response(
    94→      JSON.stringify({ error: "Invalid shop parameter" }),
    95→      { status: 400, headers: CORS_HEADERS },
    96→    );
    97→  }
    98→
    99→  // Enforce input length limits to prevent abuse
   100→  if (zip.length > 20) {
   101→    return new Response(
   102→      JSON.stringify({ error: "Invalid zip code" }),
   103→      { status: 400, headers: CORS_HEADERS },
   104→    );
   105→  }
   106→
   107→  const normalizedZip = normalizeZipCode(zip);
   108→
   109→  try {
   110→  const zipRecord = await db.zipCode.findUnique({
   111→    where: { shop_zipCode: { shop, zipCode: normalizedZip } },
   112→  });
   113→
   114→  // Fetch widget config for custom messages (falls back to defaults)
   115→  const widgetConfig = await db.widgetConfig.findUnique({ where: { shop } });
   116→
   117→  // Fetch shop settings to determine default behavior for unlisted zip codes
   118→  const shopSettings = await db.shopSettings.findUnique({ where: { shop } });
   119→  const defaultBehavior = shopSettings?.defaultBehavior ?? "block";
   120→
   121→  if (!zipRecord || !zipRecord.isActive) {
   122→    const notFoundMsg =
   123→      widgetConfig?.notFoundMessage ??
   124→      "We currently do not ship to this ZIP code.";
   125→
   126→    // If the zip is simply not in the list (not inactive) and the merchant
   127→    // has set defaultBehavior to "allow", treat it as an allowed zip
   128→    if (!zipRecord && defaultBehavior === "allow") {
   129→      const successMsg =
   130→        widgetConfig?.successMessage ?? "We deliver to your area!";
   131→      return new Response(
   132→        JSON.stringify({
   133→          allowed: true,
   134→          message: successMsg,
   135→          eta: null,
   136→          zone: null,
   137→          codAvailable: null,
   138→          returnPolicy: null,
   139→          showWaitlist: false,
   140→          waitlistCount: 0,
   141→          cutoffTime: null,
   142→          daysOfWeek: null,
   143→        }),
   144→        { status: 200, headers: SUCCESS_HEADERS },
   145→      );
   146→    }
   147→
   148→    // Social proof: count how many customers are waiting for this ZIP
   149→    let waitlistCount = 0;
   150→    try {
   151→      waitlistCount = await db.waitlistEntry.count({
   152→        where: { shop, zipCode: normalizedZip, status: "waiting" },
   153→      });
   154→    } catch {
   155→      waitlistCount = 0;
   156→    }
   157→
   158→    if (!zipRecord) {
   159→      return new Response(
   160→        JSON.stringify({
   161→          allowed: false,
   162→          message: notFoundMsg,
   163→          notFound: true,
   164→          showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
   165→          waitlistCount,
   166→        }),
   167→        { status: 200, headers: DENY_HEADERS },
   168→      );
   169→    }
   170→
   171→    // Inactive zip — treat same as not found regardless of defaultBehavior
   172→    return new Response(
   173→      JSON.stringify({
   174→        allowed: false,
   175→        message: notFoundMsg,
   176→        notFound: true,
   177→        showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
   178→        waitlistCount,
   179→      }),
   180→      { status: 200, headers: DENY_HEADERS },
   181→    );
   182→  }
   183→
   184→  if (zipRecord.type === "blocked") {
   185→    const errorMsg =
   186→      zipRecord.message ??
   187→      widgetConfig?.errorMessage ??
   188→      "Sorry, we don't deliver to this area yet.";
   189→
   190→    // Social proof: count how many customers are waiting for this ZIP
   191→    let waitlistCount = 0;
   192→    try {
   193→      waitlistCount = await db.waitlistEntry.count({
   194→        where: { shop, zipCode: normalizedZip, status: "waiting" },
   195→      });
   196→    } catch {
   197→      waitlistCount = 0;
   198→    }
   199→
   200→    return new Response(
   201→      JSON.stringify({
   202→        allowed: false,
   203→        message: errorMsg,
   204→        showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
   205→        waitlistCount,
   206→      }),
   207→      { status: 200, headers: DENY_HEADERS },
   208→    );
   209→  }
   210→
   211→  // Fetch the most relevant active DeliveryRule for this zip.
   212→  // Priority 1: rules that explicitly list this zip in their zipCodes field.
   213→  // Priority 2: rules that match by zone (with no explicit zip list).
   214→  // Within each priority tier, order by `priority ASC` (lower = higher priority).
   215→  const zipCodeUpper = normalizedZip;
   216→  const zipZone = zipRecord.zone ?? null;
   217→
   218→  // Fetch all active rules for the shop ordered by priority so we can apply
   219→  // the matching logic in a single query result.
   220→  const activeRules = await db.deliveryRule.findMany({
   221→    where: { shop, isActive: true },
   222→    orderBy: { priority: "asc" },
   223→  });
   224→
   225→  let matchedRule: (typeof activeRules)[number] | null = null;
   226→
   227→  // Pass 1: explicit zip match — zipCodes field contains this zip code
   228→  for (const rule of activeRules) {
   229→    if (rule.zipCodes) {
   230→      const zips = rule.zipCodes.split(",").map((z) => z.trim().toUpperCase());
   231→      if (zips.includes(zipCodeUpper)) {
   232→        matchedRule = rule;
   233→        break;
   234→      }
   235→    }
   236→  }
   237→
   238→  // Pass 2: zone match — rule's zone matches the zip's zone and no explicit zip list
   239→  if (!matchedRule && zipZone) {
   240→    for (const rule of activeRules) {
   241→      if (
   242→        rule.zone === zipZone &&
   243→        (!rule.zipCodes || rule.zipCodes.trim() === "")
   244→      ) {
   245→        matchedRule = rule;
   246→        break;
   247→      }
   248→    }
   249→  }
   250→
   251→  // Allowed
   252→  const successMsg =
   253→    zipRecord.message ??
   254→    widgetConfig?.successMessage ??
   255→    "Great news! We deliver to your area.";
   256→
   257→  // ETA: prefer the zip-level eta, then fall back to the matched delivery rule's
   258→  // estimatedDays so merchants only need to populate one place.
   259→  const etaValue = zipRecord.eta ?? matchedRule?.estimatedDays ?? null;
   260→
   261→  const estimatedDeliveryDate =
   262→    widgetConfig?.showDeliveryDate !== false && etaValue
   263→      ? calculateDeliveryDate(etaValue, matchedRule?.daysOfWeek ?? null)
   264→      : null;
   265→
   266→  const deliveryFeeValue =
   267→    widgetConfig?.showDeliveryFee !== false
   268→      ? (matchedRule?.deliveryFee ?? null)
   269→      : null;
   270→  const freeShippingAboveValue =
   271→    widgetConfig?.showDeliveryFee !== false
   272→      ? (matchedRule?.freeShippingAbove ?? null)
   273→      : null;
   274→
   275→  return new Response(
   276→    JSON.stringify({
   277→      allowed: true,
   278→      message: successMsg,
   279→      eta: widgetConfig?.showEta ? etaValue : null,
   280→      zone: widgetConfig?.showZone ? (zipRecord.zone ?? null) : null,
   281→      codAvailable: widgetConfig?.showCod !== false ? (zipRecord.codAvailable ?? null) : null,
   282→      returnPolicy: widgetConfig?.showReturnPolicy !== false ? (zipRecord.returnPolicy ?? null) : null,
   283→      showWaitlist: false,
   284→      waitlistCount: 0,
   285→      cutoffTime: widgetConfig?.showCutoffTime !== false ? (matchedRule?.cutoffTime ?? null) : null,
   286→      daysOfWeek: widgetConfig?.showDeliveryDays !== false ? (matchedRule?.daysOfWeek ?? null) : null,
   287→      estimatedDeliveryDate,
   288→      deliveryFee: deliveryFeeValue,
   289→      freeShippingAbove: freeShippingAboveValue,
   290→    }),
   291→    { status: 200, headers: SUCCESS_HEADERS },
   292→  );
   293→  } catch (err) {
   294→    console.error("[api.zip-check] Unhandled error for shop=%s zip=%s:", shop, zip, err);
   295→    return new Response(
   296→      JSON.stringify({ error: "Internal server error" }),
   297→      { status: 500, headers: CORS_HEADERS },
   298→    );
   299→  }
   300→}
   301→
   302→// Handle GET requests: ?shop=...&zip=...
   303→export const loader = async ({ request }: LoaderFunctionArgs) => {
   304→  const url = new URL(request.url);
   305→
   306→  // Handle CORS preflight
   307→  if (request.method === "OPTIONS") {
   308→    return new Response(null, { status: 204, headers: CORS_HEADERS });
   309→  }
   310→
   311→  const shop = url.searchParams.get("shop");
   312→  const zip = url.searchParams.get("zip");
   313→  return handleZipCheck(shop, zip);
   314→};
   315→
   316→// Handle POST requests with JSON body: { shop, zip }
   317→export const action = async ({ request }: ActionFunctionArgs) => {
   318→  let shop: string | null = null;
   319→  let zip: string | null = null;
   320→
   321→  try {
   322→    const body = await request.json();
   323→    shop = body?.shop ?? null;
   324→    zip = body?.zip ?? null;
   325→  } catch {
   326→    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
   327→      status: 400,
   328→      headers: CORS_HEADERS,
   329→    });
   330→  }
   331→
   332→  return handleZipCheck(shop, zip);
   333→};
